CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, contact_number VARCHAR(30) NOT NULL UNIQUE, email VARCHAR(254) UNIQUE NULL, password_hash TEXT NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'farmer', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE farmer_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, address TEXT NOT NULL, barangay VARCHAR(120) NULL, registration_status VARCHAR(30) NOT NULL DEFAULT 'pending', review_notes TEXT NULL, reviewed_by BIGINT UNSIGNED NULL, reviewed_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE lands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farmer_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NULL, address TEXT NULL, barangay VARCHAR(120) NULL, latitude DECIMAL(9,6) NOT NULL, longitude DECIMAL(9,6) NOT NULL, size_hectares DECIMAL(10,2) NOT NULL, crop_types JSON NOT NULL, ownership_proof_file TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (farmer_id) REFERENCES farmer_profiles(id) ON DELETE CASCADE);
CREATE TABLE damage_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, land_id BIGINT UNSIGNED NOT NULL, farmer_id BIGINT UNSIGNED NOT NULL, ai_detected_plant VARCHAR(120) NULL, ai_detected_damage_type VARCHAR(120) NULL, ai_confidence_notes TEXT NULL, confirmed_plant VARCHAR(120) NULL, confirmed_damage_type VARCHAR(120) NULL, farmer_notes TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', reviewed_by BIGINT UNSIGNED NULL, reviewed_at TIMESTAMP NULL, rejection_reason TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (land_id) REFERENCES lands(id) ON DELETE RESTRICT, FOREIGN KEY (farmer_id) REFERENCES farmer_profiles(id) ON DELETE RESTRICT, FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE report_photos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, damage_report_id BIGINT UNSIGNED NOT NULL, file_url TEXT NOT NULL, latitude DECIMAL(9,6) NULL, longitude DECIMAL(9,6) NULL, captured_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (damage_report_id) REFERENCES damage_reports(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farmer_id BIGINT UNSIGNED NOT NULL, created_by BIGINT UNSIGNED NULL, report_id BIGINT UNSIGNED NULL, message TEXT NOT NULL, type VARCHAR(30) NOT NULL, read_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (farmer_id) REFERENCES farmer_profiles(id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (report_id) REFERENCES damage_reports(id) ON DELETE SET NULL);
CREATE TABLE weather_snapshots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, land_id BIGINT UNSIGNED NOT NULL, fetched_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, condition_summary TEXT NOT NULL, forecast_data JSON NOT NULL, FOREIGN KEY (land_id) REFERENCES lands(id) ON DELETE CASCADE);
CREATE INDEX idx_profiles_status ON farmer_profiles (registration_status); CREATE INDEX idx_lands_farmer ON lands (farmer_id); CREATE INDEX idx_reports_status_created ON damage_reports (status, created_at); CREATE INDEX idx_reports_farmer ON damage_reports (farmer_id); CREATE INDEX idx_notifications_farmer ON notifications (farmer_id, read_at);
